* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: #f4f7f6;
    color: #333;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background: #ffffff;
    padding: 2.5rem;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.08);
    text-align: center;
    max-width: 400px;
    width: 100%;
}

h1 {
    font-size: 1.75rem;
    margin-bottom: 0.75rem;
    color: #2c3e50;
}

p {
    font-size: 1rem;
    margin-bottom: 1.5rem;
    color: #666;
}

.btn {
    background-color: #3498db;
    color: white;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.2s ease, transform 0.1s ease;
}

.btn:hover {
    background-color: #2980b9;
}

.btn:active {
    transform: scale(0.98);
}

.output {
    margin-top: 1.25rem;
    font-size: 0.95rem;
    color: #27ae60;
    font-weight: 500;
    min-height: 1.5rem;
}

document.addEventListener('DOMContentLoaded', () => {
    const button = document.getElementById('action-btn');
    const output = document.getElementById('output');

    let clickCount = 0;

    button.addEventListener('click', () => {
        clickCount++;
        if (clickCount === 1) {
            output.textContent = 'Button clicked 1 time!';
        } else {
            output.textContent = `Button clicked ${clickCount} times!`;
        }
    });
});

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: #05050a;
    color: #00ffff;
    font-family: 'Orbitron', sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    overflow: hidden;
}

.game-container {
    position: relative;
    width: 840px;
    background: #0b0b16;
    border: 2px solid #00ffff;
    border-radius: 8px;
    box-shadow: 0 0 25px rgba(0, 255, 255, 0.4), inset 0 0 15px rgba(0, 255, 255, 0.2);
    padding: 20px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

/* CRT Scanline Effect */
.crt {
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
    background-size: 100% 4px, 6px 100%;
    pointer-events: none;
    z-index: 10;
    border-radius: 6px;
}

.hud {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 15px;
    padding: 0 10px;
}

.hud-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.hud-item .label {
    font-size: 0.75rem;
    color: #ff007f;
    letter-spacing: 2px;
    margin-bottom: 2px;
}

.hud-item .value {
    font-size: 1.25rem;
    font-weight: 700;
    color: #00ffff;
    text-shadow: 0 0 8px rgba(0, 255, 255, 0.6);
}

.canvas-wrapper {
    position: relative;
    width: 800px;
    height: 400px;
    border: 1px solid #ff007f;
    border-radius: 4px;
    overflow: hidden;
    background: #020205;
    box-shadow: inset 0 0 20px rgba(255, 0, 127, 0.3);
}

canvas {
    display: block;
    width: 800px;
    height: 400px;
}

/* Overlays */
.overlay {
    position: absolute;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(5, 5, 10, 0.88);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 20;
    backdrop-filter: blur(3px);
    transition: opacity 0.3s ease;
}

.overlay.hidden {
    opacity: 0;
    pointer-events: none;
}

.menu-content {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
    padding: 20px;
}

/* Glitch Title Effect */
.glitch {
    font-size: 2.5rem;
    font-weight: 900;
    color: #00ffff;
    position: relative;
    letter-spacing: 3px;
    text-shadow: 0 0 10px rgba(0, 255, 255, 0.8);
    animation: pulseGlow 2s infinite alternate;
}

.subtitle {
    font-size: 0.85rem;
    color: #a0a0c0;
    max-width: 450px;
    line-height: 1.4;
}

.controls-hint {
    display: flex;
    gap: 15px;
    font-size: 0.7rem;
    color: #ff007f;
    background: rgba(255, 0, 127, 0.1);
    border: 1px dashed #ff007f;
    padding: 8px 12px;
    border-radius: 4px;
    margin: 5px 0 15px 0;
}

.game-over-title {
    font-size: 2.2rem;
    color: #ff0055;
    text-shadow: 0 0 15px rgba(255, 0, 85, 0.8);
    letter-spacing: 2px;
}

.final-score-text {
    font-size: 1.1rem;
    color: #fff;
    margin-bottom: 10px;
}

/* Cyber Button */
.cyber-btn {
    background: transparent;
    color: #00ffff;
    border: 2px solid #00ffff;
    padding: 12px 30px;
    font-family: 'Orbitron', sans-serif;
    font-size: 1rem;
    font-weight: 700;
    letter-spacing: 2px;
    cursor: pointer;
    border-radius: 4px;
    position: relative;
    overflow: hidden;
    transition: all 0.2s ease;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.3);
}

.cyber-btn:hover {
    background: #00ffff;
    color: #05050a;
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.8);
    transform: translateY(-2px);
}

.cyber-btn:active {
    transform: translateY(0);
}

/* Mobile Controls */
.mobile-controls {
    display: none;
    width: 100%;
    justify-content: space-between;
    margin-top: 15px;
    gap: 10px;
}

.touch-btn {
    flex: 1;
    background: rgba(0, 255, 255, 0.1);
    border: 1px solid #00ffff;
    color: #00ffff;
    padding: 12px;
    font-family: 'Orbitron', sans-serif;
    font-weight: 700;
    border-radius: 4px;
    cursor: pointer;
}

.touch-btn:active {
    background: rgba(0, 255, 255, 0.3);
}

@keyframes pulseGlow {
    0% { text-shadow: 0 0 10px rgba(0, 255, 255, 0.8), 0 0 20px rgba(0, 255, 255, 0.4); }
    100% { text-shadow: 0 0 15px rgba(255, 0, 127, 0.8), 0 0 30px rgba(255, 0, 127, 0.6); }
}

@media (max-width: 860px) {
    .game-container {
        width: 100%;
        max-width: 840px;
        padding: 10px;
    }
    .canvas-wrapper {
        width: 100%;
        height: auto;
    }
    canvas {
        width: 100%;
        height: auto;
    }
    .mobile-controls {
        display: flex;
    }
}

// --- CANVAS & CONTEXT ---
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// --- UI ELEMENTS ---
const scoreEl = document.getElementById('scoreVal');
const highScoreEl = document.getElementById('highScoreVal');
const speedEl = document.getElementById('speedVal');
const finalScoreEl = document.getElementById('finalScore');

const menuOverlay = document.getElementById('menuOverlay');
const pauseOverlay = document.getElementById('pauseOverlay');
const gameOverOverlay = document.getElementById('gameOverOverlay');

const startBtn = document.getElementById('startBtn');
const resumeBtn = document.getElementById('resumeBtn');
const restartBtn = document.getElementById('restartBtn');
const jumpBtn = document.getElementById('jumpBtn');
const slideBtn = document.getElementById('slideBtn');

// --- GAME STATES ---
const GAME_STATE = {
    MENU: 'MENU',
    PLAYING: 'PLAYING',
    PAUSED: 'PAUSED',
    GAMEOVER: 'GAMEOVER'
};
let currentState = GAME_STATE.MENU;

// --- GAME VARIABLES ---
let score = 0;
let highScore = localStorage.getItem('cyber_runner_highscore') || 0;
let gameSpeed = 5;
let baseSpeed = 5;
let maxSpeed = 14;
let speedIncrement = 0.0008;
let gravity = 0.8;

highScoreEl.textContent = Math.floor(highScore);

// --- PLAYER OBJECT ---
const player = {
    x: 80,
    y: 280,
    width: 36,
    height: 52,
    baseHeight: 52,
    slideHeight: 28,
    vy: 0,
    jumpForce: -13.5,
    isJumping: false,
    isSliding: false,
    color: '#00ffff',
    glowColor: 'rgba(0, 255, 255, 0.8)',
    trail: []
};

// --- WORLD ARRAYS ---
let obstacles = [];
let particles = [];
let floatingTexts = [];
let powerUps = [];
let groundY = 328;

// Shield power-up state
let hasShield = false;
let shieldTimer = 0;

// --- BACKGROUND GRID & NEON SCENERY ---
let gridOffset = 0;
let buildings = [];
let stars = [];

// Initialize background buildings
for (let i = 0; i < 10; i++) {
    buildings.push({
        x: i * 90,
        width: 70 + Math.random() * 50,
        height: 120 + Math.random() * 150,
        speedFactor: 0.3,
        color: Math.random() > 0.5 ? '#120b29' : '#180e38'
    });
}

// Initialize stars / dust
for (let i = 0; i < 40; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (groundY - 50),
        size: Math.random() * 2,
        speedFactor: 0.1 + Math.random() * 0.2
    });
}

// --- INPUT LISTENERS ---
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        if (currentState === GAME_STATE.PLAYING) {
            jump();
        } else if (currentState === GAME_STATE.MENU) {
            startGame();
        } else if (currentState === GAME_STATE.GAMEOVER) {
            resetGame();
        }
    }
    if (e.code === 'ArrowDown') {
        e.preventDefault();
        if (currentState === GAME_STATE.PLAYING) {
            slide(true);
        }
    }
    if (e.code === 'KeyP') {
        if (currentState === GAME_STATE.PLAYING) {
            pauseGame();
        } else if (currentState === GAME_STATE.PAUSED) {
            resumeGame();
        }
    }
});

window.addEventListener('keyup', (e) => {
    if (e.code === 'ArrowDown') {
        if (currentState === GAME_STATE.PLAYING) {
            slide(false);
        }
    }
});

startBtn.addEventListener('click', startGame);
resumeBtn.addEventListener('click', resumeGame);
restartBtn.addEventListener('click', resetGame);

// Touch controls for mobile
jumpBtn.addEventListener('touchstart', (e) => {
    e.preventDefault();
    if (currentState === GAME_STATE.PLAYING) jump();
});
slideBtn.addEventListener('touchstart', (e) => {
    e.preventDefault();
    if (currentState === GAME_STATE.PLAYING) slide(true);
});
slideBtn.addEventListener('touchend', (e) => {
    e.preventDefault();
    if (currentState === GAME_STATE.PLAYING) slide(false);
});

// --- GAME LOGIC FUNCTIONS ---

function startGame() {
    currentState = GAME_STATE.PLAYING;
    menuOverlay.classList.add('hidden');
    score = 0;
    gameSpeed = baseSpeed;
    obstacles = [];
    particles = [];
    floatingTexts = [];
    powerUps = [];
    hasShield = false;
    player.y = groundY - player.height;
    player.vy = 0;
    player.isJumping = false;
    player.isSliding = false;
}

function pauseGame() {
    currentState = GAME_STATE.PAUSED;
    pauseOverlay.classList.remove('hidden');
}

function resumeGame() {
    currentState = GAME_STATE.PLAYING;
    pauseOverlay.classList.add('hidden');
}

function gameOver() {
    currentState = GAME_STATE.GAMEOVER;
    finalScoreEl.textContent = Math.floor(score);
    if (score > highScore) {
        highScore = score;
        localStorage.setItem('cyber_runner_highscore', highScore);
        highScoreEl.textContent = Math.floor(highScore);
    }
    gameOverOverlay.classList.remove('hidden');
}

function resetGame() {
    gameOverOverlay.classList.add('hidden');
    startGame();
}

function jump() {
    if (!player.isJumping) {
        if (player.isSliding) {
            slide(false); // Cancel slide if jumping
        }
        player.vy = player.jumpForce;
        player.isJumping = true;
        createParticles(player.x + player.width / 2, groundY, '#00ffff', 10);
    }
}

function slide(isDown) {
    if (isDown && !player.isJumping) {
        if (!player.isSliding) {
            player.isSliding = true;
            player.height = player.slideHeight;
            player.y = groundY - player.height;
        }
    } else {
        if (player.isSliding) {
            player.isSliding = false;
            player.height = player.baseHeight;
            player.y = groundY - player.height;
        }
    }
}

// --- SPAWNING ENTITIES ---
let obstacleTimer = 0;
let obstacleInterval = 90;

function spawnObstacle() {
    const rand = Math.random();
    let type = 'ground';
    let height = 40 + Math.random() * 25;
    let width = 24 + Math.random() * 16;
    let y = groundY - height;
    let color = '#ff0055';

    if (rand < 0.35) {
        // High barrier (Player must slide)
        type = 'high';
        height = 30;
        width = 45;
        y = groundY - 78; // floating above ground
        color = '#ff9900';
    } else if (rand < 0.65) {
        // Tall drone / obstacle
        type = 'tall';
        height = 65;
        width = 28;
        y = groundY - height;
        color = '#bf00ff';
    } else {
        // Standard ground spike / block
        type = 'ground';
        height = 42;
        width = 30;
        y = groundY - height;
        color = '#ff0055';
    }

    obstacles.push({
        x: canvas.width + 50,
        y: y,
        width: width,
        height: height,
        type: type,
        color: color,
        passed: false
    });
}

// Spawn Powerups periodically
let powerUpTimer = 0;
let powerUpInterval = 450;

function spawnPowerUp() {
    const types = ['shield', 'points'];
    const selectedType = types[Math.floor(Math.random() * types.length)];
    powerUps.push({
        x: canvas.width + 50,
        y: groundY - 90 - Math.random() * 60,
        width: 26,
        height: 26,
        type: selectedType,
        angle: 0
    });
}

// --- PARTICLE EFFECTS ---
function createParticles(x, y, color, count) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 6,
            vy: (Math.random() - 0.5) * 6,
            size: 2 + Math.random() * 3,
            color: color,
            alpha: 1,
            decay: 0.03 + Math.random() * 0.04
        });
    }
}

function addFloatingText(text, x, y, color = '#00ffff') {
    floatingTexts.push({
        text: text,
        x: x,
        y: y,
        vy: -1.5,
        alpha: 1,
        color: color
    });
}

// --- MAIN UPDATE LOOP ---
function update() {
    if (currentState !== GAME_STATE.PLAYING) return;

    // Increment speed & score
    gameSpeed = Math.min(maxSpeed, baseSpeed + (score * speedIncrement));
    score += 0.1 * (gameSpeed / baseSpeed);

    speedEl.textContent = (gameSpeed / baseSpeed).toFixed(1) + 'X';
    scoreEl.textContent = Math.floor(score);

    // Shield timer
    if (hasShield) {
        shieldTimer--;
        if (shieldTimer <= 0) {
            hasShield = false;
        }
    }

    // Player Physics
    player.vy += gravity;
    player.y += player.vy;

    // Ground collision
    if (player.y >= groundY - player.height) {
        player.y = groundY - player.height;
        player.vy = 0;
        player.isJumping = false;
    }

    // Running trail effect
    if (!player.isJumping && Math.random() > 0.4) {
        player.trail.push({ x: player.x, y: player.y, height: player.height, alpha: 0.5 });
    }
    for (let i = player.trail.length - 1; i >= 0; i--) {
        player.trail[i].x -= gameSpeed * 0.5;
        player.trail[i].alpha -= 0.05;
        if (player.trail[i].alpha <= 0) {
            player.trail.splice(i, 1);
        }
    }

    // Background grid & scenery scroll
    gridOffset = (gridOffset + gameSpeed) % 40;

    buildings.forEach(b => {
        b.x -= gameSpeed * b.speedFactor;
        if (b.x + b.width < 0) {
            b.x = canvas.width + Math.random() * 50;
            b.height = 120 + Math.random() * 150;
        }
    });

    stars.forEach(s => {
        s.x -= gameSpeed * s.speedFactor;
        if (s.x < 0) s.x = canvas.width;
    });

    // Obstacles Management
    obstacleTimer++;
    if (obstacleTimer >= obstacleInterval / (gameSpeed / baseSpeed)) {
        spawnObstacle();
        obstacleTimer = 0;
        // Randomize next interval slightly
        obstacleInterval = 70 + Math.random() * 60;
    }

    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        // Collision Check (AABB with slight padding for fairness)
        let padding = 6;
        if (
            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            if (hasShield) {
                hasShield = false;
                createParticles(obs.x + obs.width / 2, obs.y + obs.height / 2, '#00ffff', 25);
                addFloatingText('SHIELD BREAK!', obs.x, obs.y - 10, '#00ffff');
                obstacles.splice(i, 1);
                continue;
            } else {
                createParticles(player.x + player.width / 2, player.y + player.height / 2, '#ff0055', 30);
                gameOver();
                return;
            }
        }

        // Remove offscreen obstacles
        if (obs.x + obs.width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Power-ups Management
    powerUpTimer++;
    if (powerUpTimer >= powerUpInterval) {
        spawnPowerUp();
        powerUpTimer = 0;
        powerUpInterval = 400 + Math.random() * 300;
    }

    for (let i = powerUps.length - 1; i >= 0; i--) {
        let p = powerUps[i];
        p.x -= gameSpeed;
        p.angle += 0.05;

        // Collision with player
        if (
            player.x < p.x + p.width &&
            player.x + player.width > p.x &&
            player.y < p.y + p.height &&
            player.y + player.height > p.y
        ) {
            if (p.type === 'shield') {
                hasShield = true;
                shieldTimer = 400; // duration frames
                createParticles(p.x, p.y, '#00ffff', 15);
                addFloatingText('SHIELD ACTIVATED!', p.x, p.y - 15, '#00ffff');
            } else if (p.type === 'points') {
                score += 250;
                createParticles(p.x, p.y, '#ff00ff', 15);
                addFloatingText('+250 PTS', p.x, p.y - 15, '#ff00ff');
            }
            powerUps.splice(i, 1);
            continue;
        }

        if (p.x + p.width < 0) {
            powerUps.splice(i, 1);
        }
    }

    // Particles Update
    for (let i = particles.length - 1; i >= 0; i--) {
        let pt = particles[i];
        pt.x += pt.vx;
        pt.y += pt.vy;
        pt.alpha -= pt.decay;
        if (pt.alpha <= 0) {
            particles.splice(i, 1);
        }
    }

    // Floating Text Update
    for (let i = floatingTexts.length - 1; i >= 0; i--) {
        let ft = floatingTexts[i];
        ft.y += ft.vy;
        ft.alpha -= 0.02;
        if (ft.alpha <= 0) {
            floatingTexts.splice(i, 1);
        }
    }
}

// --- MAIN RENDER LOOP ---
function draw() {
    // Clear Canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 1. Draw Background Space / Deep Cyber Sky
    let gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#05030a');
    gradient.addColorStop(1, '#0c071e');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 2. Draw Stars / Dust
    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
    stars.forEach(s => {
        ctx.fillRect(s.x, s.y, s.size, s.size);
    });

    // 3. Draw Background Buildings (Cyber Skyline)
    buildings.forEach(b => {
        ctx.fillStyle = b.color;
        ctx.fillRect(b.x, groundY - b.height, b.width, b.height);

        // Windows grid glow
        ctx.fillStyle = 'rgba(0, 255, 255, 0.08)';
        for (let wy = groundY - b.height + 10; wy < groundY - 15; wy += 20) {
            for (let wx = b.x + 8; wx < b.x + b.width - 8; wx += 14) {
                if ((wx + wy) % 3 === 0) {
                    ctx.fillRect(wx, wy, 6, 10);
                }
            }
        }
    });

    // 4. Draw Perspective Floor Grid
    ctx.strokeStyle = 'rgba(255, 0, 127, 0.25)';
    ctx.lineWidth = 1;

    // Horizontal grid lines
    ctx.beginPath();
    ctx.moveTo(0, groundY);
    ctx.lineTo(canvas.width, groundY);
    ctx.stroke();

    // Moving vertical grid lines
    for (let x = -gridOffset; x < canvas.width; x += 40) {
        ctx.beginPath();
        ctx.moveTo(x, groundY);
        ctx.lineTo(x - 60, canvas.height);
        ctx.strokeStyle = 'rgba(0, 255, 255, 0.15)';
        ctx.stroke();
    }

    // Ground solid line neon glow
    ctx.strokeStyle = '#00ffff';
    ctx.shadowColor = '#00ffff';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.moveTo(0, groundY);
    ctx.lineTo(canvas.width, groundY);
    ctx.stroke();
    ctx.shadowBlur = 0; // reset shadow

    // 5. Draw Player Trail
    player.trail.forEach(t => {
        ctx.fillStyle = `rgba(0, 255, 255, ${t.alpha})`;
        ctx.fillRect(t.x, t.y, player.width, t.height);
    });

    // 6. Draw Player (Cyber Runner Avatar)
    ctx.save();
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 12;
    ctx.fillStyle = player.color;

    // Body
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Visor / Helmet Glow
    ctx.fillStyle = '#ff007f';
    if (!player.isSliding) {
        ctx.fillRect(player.x + player.width - 14, player.y + 8, 10, 6);
    } else {
        ctx.fillRect(player.x + player.width - 12, player.y + 6, 8, 4);
    }

    // Shield Aura if active
    if (hasShield) {
        ctx.strokeStyle = '#00ffff';
        ctx.lineWidth = 2;
        ctx.shadowColor = '#00ffff';
        ctx.shadowBlur = 15;
        ctx.strokeRect(player.x - 5, player.y - 5, player.width + 10, player.height + 10);
    }
    ctx.restore();

    // 7. Draw Obstacles
    obstacles.forEach(obs => {
        ctx.save();
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 12;
        ctx.fillStyle = obs.color;

        if (obs.type === 'high') {
            // Floating barrier / laser bar
            ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
            // Core glowing stripe
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(obs.x, obs.y + obs.height / 2 - 2, obs.width, 4);
        } else if (obs.type === 'tall') {
            // Tall server stack / glitch pillar
            ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
            // Glitch lines
            ctx.fillStyle = '#00ffff';
            ctx.fillRect(obs.x + 4, obs.y + 10, obs.width - 8, 4);
            ctx.fillRect(obs.x + 4, obs.y + 30, obs.width - 8, 4);
        } else {
            // Ground spike / firewall block
            ctx.beginPath();
            ctx.moveTo(obs.x, obs.y + obs.height);
            ctx.lineTo(obs.x + obs.width / 2, obs.y);
            ctx.lineTo(obs.x + obs.width, obs.y + obs.height);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    });

    // 8. Draw Power-Ups
    powerUps.forEach(p => {
        ctx.save();
        ctx.translate(p.x + p.width / 2, p.y + p.height / 2);
        ctx.rotate(p.angle);
        ctx.shadowColor = p.type === 'shield' ? '#00ffff' : '#ff00ff';
        ctx.shadowBlur = 12;
        ctx.strokeStyle = p.type === 'shield' ? '#00ffff' : '#ff00ff';
        ctx.lineWidth = 3;

        if (p.type === 'shield') {
            ctx.strokeRect(-p.width / 2, -p.height / 2, p.width, p.height);
            ctx.fillStyle = 'rgba(0, 255, 255, 0.3)';
            ctx.fillRect(-p.width / 2, -p.height / 2, p.width, p.height);
        } else {
            // Star or diamond for points
            ctx.beginPath();
            ctx.moveTo(0, -p.height / 2);
            ctx.lineTo(p.width / 2, 0);
            ctx.lineTo(0, p.height / 2);
            ctx.lineTo(-p.width / 2, 0);
            ctx.closePath();
            ctx.fillStyle = 'rgba(255, 0, 255, 0.4)';
            ctx.fill();
            ctx.stroke();
        }
        ctx.restore();
    });

    // 9. Draw Particles
    particles.forEach(pt => {
        ctx.save();
        ctx.globalAlpha = pt.alpha;
        ctx.fillStyle = pt.color;
        ctx.shadowColor = pt.color;
        ctx.shadowBlur = 6;
        ctx.fillRect(pt.x, pt.y, pt.size, pt.size);
        ctx.restore();
    });

    // 10. Draw Floating Texts
    floatingTexts.forEach(ft => {
        ctx.save();
        ctx.globalAlpha = ft.alpha;
        ctx.font = '700 14px Orbitron';
        ctx.fillStyle = ft.color;
        ctx.shadowColor = ft.color;
        ctx.shadowBlur = 8;
        ctx.fillText(ft.text, ft.x, ft.y);
        ctx.restore();
    });
}

// --- GAME LOOP ---
function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Start loop
requestAnimationFrame(gameLoop);

