const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');
const finalScoreEl = document.getElementById('final-score');
const gameOverScreen = document.getElementById('game-over-screen');
const restartBtn = document.getElementById('restart-btn');

// Game variables
let score = 0;
let highScore = localStorage.getItem('cyberRunnerHighScore') || 0;
highScoreEl.textContent = highScore;

let gameSpeed = 5;
let isGameOver = false;
let frameCount = 0;

// Player (Cyber Runner)
const player = {
    x: 80,
    y: 280,
    width: 36,
    height: 48,
    dy: 0,
    jumpPower: -11,
    gravity: 0.6,
    grounded: false,
    jumpsLeft: 2,
    maxJumps: 2,
    color: '#00ffcc',
    trail: []
};

// Obstacles array
let obstacles = [];

// Particles array for jump / effects
let particles = [];

// Stars/Grid background elements
let stars = [];
for (let i = 0; i < 50; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (canvas.height - 80),
        size: Math.random() * 2 + 1,
        speed: Math.random() * 1.5 + 0.5
    });
}

function spawnObstacle() {
    const types = ['spike', 'tall', 'drone'];
    const type = types[Math.floor(Math.random() * types.length)];

    let obs = {
        x: canvas.width,
        width: 30,
        height: 40,
        y: 288,
        color: '#ff007f',
        type: type
    };

    if (type === 'tall') {
        obs.width = 34;
        obs.height = 65;
        obs.y = 263;
        obs.color = '#7f00ff';
    } else if (type === 'drone') {
        obs.width = 40;
        obs.height = 25;
        obs.y = 200 + (Math.random() > 0.5 ? 0 : -40); // floating drone
        obs.color = '#ffaa00';
    }

    obstacles.push(obs);
}

function createParticles(x, y, color, count = 10) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x,
            y: y,
            dx: (Math.random() - 0.5) * 6,
            dy: (Math.random() - 0.5) * 6,
            radius: Math.random() * 3 + 1,
            color: color,
            life: 30
        });
    }
}

function jump() {
    if (isGameOver) return;

    if (player.jumpsLeft > 0) {
        player.dy = player.jumpPower;
        player.grounded = false;
        player.jumpsLeft--;

        // Spawn jump particles / effects
        const pColor = player.jumpsLeft === 1 ? '#00ffcc' : '#ff007f';
        createParticles(player.x + player.width / 2, player.y + player.height, pColor, 12);
    }
}

// Input listeners
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        jump();
    }
    if ((e.code === 'KeyR' || e.code === 'Enter') && isGameOver) {
        resetGame();
    }
});

canvas.addEventListener('mousedown', () => {
    if (isGameOver) {
        resetGame();
    } else {
        jump();
    }
});

restartBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    resetGame();
});

function resetGame() {
    score = 0;
    scoreEl.textContent = score;
    gameSpeed = 5;
    obstacles = [];
    particles = [];
    player.y = 280;
    player.dy = 0;
    player.jumpsLeft = player.maxJumps;
    player.grounded = true;
    isGameOver = false;
    gameOverScreen.classList.add('hidden');
    frameCount = 0;
}

function update() {
    if (isGameOver) return;

    frameCount++;
    score += 0.1;
    scoreEl.textContent = Math.floor(score);

    // Increase speed gradually
    if (frameCount % 500 === 0) {
        gameSpeed += 0.5;
    }

    // Player physics
    player.dy += player.gravity;
    player.y += player.dy;

    // Ground collision
    const groundLevel = 328 - player.height;
    if (player.y > groundLevel) {
        player.y = groundLevel;
        player.dy = 0;
        player.grounded = true;
        player.jumpsLeft = player.maxJumps;
    }

    // Player trail
    if (frameCount % 3 === 0) {
        player.trail.push({ x: player.x, y: player.y, alpha: 0.5 });
        if (player.trail.length > 5) {
            player.trail.shift();
        }
    }
    player.trail.forEach(t => t.alpha -= 0.1);

    // Background stars movement
    stars.forEach(star => {
        star.x -= star.speed * (gameSpeed / 4);
        if (star.x < 0) star.x = canvas.width;
    });

    // Spawn obstacles
    if (frameCount % Math.max(70, Math.floor(140 - gameSpeed * 8)) === 0) {
        spawnObstacle();
    }

    // Update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        // Collision detection (AABB with slight padding for fairness)
        const padding = 6;
        if (
            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            isGameOver = true;
            createParticles(player.x + player.width / 2, player.y + player.height / 2, '#ff007f', 30);

            if (Math.floor(score) > highScore) {
                highScore = Math.floor(score);
                localStorage.setItem('cyberRunnerHighScore', highScore);
                highScoreEl.textContent = highScore;
            }
            finalScoreEl.textContent = Math.floor(score);
            gameOverScreen.classList.remove('hidden');
        }

        // Remove offscreen obstacles
        if (obs.x + obs.width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.dx;
        p.y += p.dy;
        p.life--;
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }
}

function draw() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background stars/grid
    ctx.fillStyle = '#ffffff';
    stars.forEach(star => {
        ctx.globalAlpha = Math.random() * 0.5 + 0.3;
        ctx.fillRect(star.x, star.y, star.size, star.size);
    });
    ctx.globalAlpha = 1.0;

    // Draw futuristic horizon grid lines
    ctx.strokeStyle = 'rgba(0, 255, 204, 0.15)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, 328);
    ctx.lineTo(canvas.width, 328);
    ctx.stroke();

    // Moving ground line
    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 3;
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#00ffcc';
    ctx.beginPath();
    ctx.moveTo(0, 328);
    ctx.lineTo(canvas.width, 328);
    ctx.stroke();
    ctx.shadowBlur = 0; // reset shadow

    // Draw player trail
    player.trail.forEach(t => {
        ctx.fillStyle = `rgba(0, 255, 204, ${t.alpha})`;
        ctx.fillRect(t.x, t.y, player.width, player.height);
    });

    // Draw player (Cyber Runner character)
    ctx.fillStyle = player.color;
    ctx.shadowBlur = 12;
    ctx.shadowColor = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Player visor / neon detail
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(player.x + 18, player.y + 10, 12, 6);
    ctx.shadowBlur = 0;

    // Draw obstacles
    obstacles.forEach(obs => {
        ctx.fillStyle = obs.color;
        ctx.shadowBlur = 10;
        ctx.shadowColor = obs.color;

        if (obs.type === 'drone') {
            // Draw drone shape
            ctx.beginPath();
            ctx.ellipse(obs.x + obs.width / 2, obs.y + obs.height / 2, obs.width / 2, obs.height / 2, 0, 0, Math.PI * 2);
            ctx.fill();
            // Drone eye
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(obs.x + 12, obs.y + 8, 16, 6);
        } else {
            // Draw spike / barrier
            ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
            // Inner highlight
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(obs.x + 4, obs.y + 4, 4, obs.height - 8);
        }
        ctx.shadowBlur = 0;
    });

    // Draw particles
    particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.life / 30;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1.0;
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

gameLoop();

